    "ddinterOriginalText": "Coadministration with other psychotropic agents may potentiate the adverse effects of clozapine on cardiovascular function. Orthostatic hypotension with or without syncope, in rare cases accompanied by profound collapse and cardiorespiratory arrest, has occurred during initiation of clozapine treatment alone and in combination with other psychotropic agents, occasionally even on the first dose. The risk is greatest during initial titration in association with rapid dose escalation. Other adverse effects that may be increased during use of clozapine with other psychotropic agents include CNS depression, tardive dyskinesia, tachycardia, and ECG changes such as QT interval prolongation. Anticholinergic effects of these agents may also be additively increased. Excessive anticholinergic effects may result in paralytic ileus, hyperthermia, heat stroke, and the anticholinergic intoxication syndrome. Peripheral symptoms of anticholinergic intoxication commonly include mydriasis, blurred vision, flushed face, fever, dry skin and mucous membranes, tachycardia, urinary retention, and constipation. Central symptoms may include memory loss, disorientation, incoherence, hallucinations, psychosis, delirium, hyperactivity, twitching or jerking movements, stereotypy, and seizures.",
    "ddinterOriginalManagement": "Caution is advised when clozapine is initiated in patients receiving other psychotropic drugs. Vital signs should be closely monitored. Patients who have had even a brief interval off clozapine (i.e. 2 or more days since the last dose) should be restarted with 12.5 mg once or twice daily. The potential for additive effects on the QT interval and increased risk of torsade de pointes arrhythmia should also be considered when clozapine is used in combination with phenothiazines, tricyclic antidepressants, some atypical antipsychotics (e.g., asenapine, quetiapine, iloperidone, iloperidone, paliperidone, risperidone, ziprasidone), or other psychotherapeutic agents that can prolong the QT interval such as amoxapine, haloperidol, maprotiline, and trazodone. Serum electrolytes, including potassium, magnesium and calcium, should be measured at baseline and periodically during treatment, and any abnormalities corrected prior to initiating clozapine. Routine ECG assessment may detect QTc prolongation but is not always effective in preventing arrhythmias. Clozapine treatment should be discontinued if the QTc interval exceeds 500 msec. Patients should be advised to seek prompt medical attention if they experience symptoms that could indicate the occurrence of torsade de pointes such as dizziness, lightheadedness, fainting, palpitation, irregular heart rhythm, shortness of breath, or syncope. Ambulatory patients may want to avoid activities requiring mental alertness until they know how these agents affect them. A dosage reduction in one or both drugs may be necessary if excessive adverse effects develop.",
    "references": [
      "Nature Protocols (2022) - DDInter: an online drug-drug interaction database with chemical and clinical profiles.",
      "Clinical Pharmacology & Therapeutics - DDInter 2.0 Monograph #2087"
    ],
