    "ddinterOriginalManagement": "Caution is advised when zonisamide is prescribed with other drugs that predispose patients to heat-related disorders, including carbonic anhydrase inhibitors and drugs with anticholinergic activity. Patients, particularly pediatric patients, should be monitored closely for evidence of decreased sweating and increased body temperature, especially in warm or hot weather. Proper hydration before and during vigorous activities or exposure to warm temperatures is recommended. Patients (or their guardians or caregivers) should contact their physician immediately if they are not sweating as usual, with or without a fever. Ambulatory patients treated with zonisamide and agents with anticholinergic activity should also be made aware of the possibility of additive CNS effects (e.g., drowsiness, dizziness, lightheadedness, confusion) and counseled to avoid activities requiring mental alertness until they know how these agents affect them.",
    "references": [
      "Nature Protocols (2022) - DDInter: an online drug-drug interaction database with chemical and clinical profiles.",
      "Clinical Pharmacology & Therapeutics - DDInter 2.0 Monograph #2091"
    ],
