    "severity": "Major",
    "mechanismCategory": "Metabolism",
    "mechanism": "Inhibisi isoenzim sitokrom hepar (seperti CYP2D6, CYP3A4, atau CYP2C19) oleh salah satu obat menghambat eliminasi obat pasangan, meningkatkan konsentrasi plasma.",
    "clinicalOutcome": "Peningkatan kadar obat dalam darah yang dapat meningkatkan frekuensi efek samping sentral atau risiko toksisitas.",
    "management": "Pantau respons neuropsikiatri dan tanda efek samping; pertimbangkan penurunan dosis obat substrat bila perlu.",
    "evidenceLevel": "Level 1 - Well Established (DDInter 2.0 / Nature Protocols 2022)",
    "ddinterPairId": "DDInter-PAIR-28513",
    "ddinterOriginalText": "Tetrabenazine may cause modest prolongation of the QT interval. Coadministration with a potent CYP450 2D6 inhibitor may increase the plasma concentrations of the pharmacologically active metabolites of tetrabenazine. However, effects at higher exposures to either tetrabenazine or its metabolites have not been evaluated. Coadministration with potent CYP450 2D6 inhibitors may significantly increase the plasma concentrations of the pharmacologically active metabolites of tetrabenazine.",
    "ddinterOriginalManagement": "Pharmacologic response to tetrabenazine should be monitored more closely whenever a potent CYP450 2D6 inhibitor (e.g., fluoxetine, paroxetine, or quinidine) is added to or withdrawn from therapy. Tetrabenazine is not recommended for use in patients with congenital long QT syndrome or with arrhythmias associated with a prolonged QT interval. Assessment of baseline QT interval and periodic monitoring during therapy may be considered. In patients already stabilized on tetrabenazine, the daily dosage of tetrabenazine should be halved. The maximum dosage recommended is 25 mg per dose and 50 mg per day during coadministration with a potent CYP450 2D6 inhibitor or in patients who are poor metabolizers of CYP450 2D6. Patients and their caregivers should be advised to notify their physician if they experience new or worsening depression, suicidal thoughts, parkinsonism, restlessness, agitation, dysphagia, and/or excessive sedation while taking tetrabenazine. Patients should also be advised to seek prompt medical attention if they experience symptoms that could indicate the occurrence of torsade de pointes such as dizziness, lightheadedness, fainting, palpitation, irregular heart rhythm, shortness of breath, or syncope.",
